// js/screens/auth.js
import { navigate, setState, toast } from '../helpers.js';
import API_URL from '../api.js';

const LOGO_SRC   = 'data:image/png;base64,';
const CAMPUS_SRC = 'data:image/jpeg;base64,';

/* ══════════════════════════════════════════════════
   LOGIN
══════════════════════════════════════════════════ */
export function renderLogin() {
  document.getElementById('app').innerHTML = `
    <div class="screen screen-enter auth-page">

      <!-- Full-screen blurred background image -->
      <img src="${CAMPUS_SRC}" class="auth-campus-img" alt="" aria-hidden="true" />
      <div class="auth-bg-overlay"></div>

      <!-- Logo + app name -->
      <div class="auth-hero-content">
        <img src="${LOGO_SRC}" class="auth-uni-logo" alt="Christ University" />
        <div class="auth-app-name">Fliqr</div>
        <div class="auth-app-tagline">Christ University · Delhi NCR</div>
      </div>

      <!-- Glass login card -->
      <div class="auth-card">
        <div class="auth-card-title">Sign in</div>

        <div class="auth-field-group">
          <div class="auth-field">
            <div class="auth-field-icon">
              <svg viewBox="0 0 20 20" fill="none"><rect x="2" y="4" width="16" height="12" rx="2" stroke="currentColor" stroke-width="1.6"/><path d="M3 6l6.5 5a1.5 1.5 0 001.8 0L18 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
            </div>
            <input id="loginEmail" type="email" placeholder="your@gmail.com" autocomplete="email" class="auth-input" />
          </div>
          <div class="auth-field">
            <div class="auth-field-icon">
              <svg viewBox="0 0 20 20" fill="none"><rect x="4" y="9" width="12" height="8" rx="1.5" stroke="currentColor" stroke-width="1.6"/><path d="M7 9V6.5a3 3 0 016 0V9" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
            </div>
            <input id="loginPassword" type="password" placeholder="••••••••" autocomplete="current-password" class="auth-input" />
          </div>
        </div>

        <button class="btn auth-btn" id="loginBtn">Sign in</button>

        <div class="auth-switch">
          Don't have an account?
          <span id="goRegister" class="auth-switch-link">Register</span>
        </div>
      </div>
    </div>`;

  document.getElementById('loginBtn').addEventListener('click', loginUser);
  document.getElementById('loginEmail').addEventListener('keydown', e => { if (e.key === 'Enter') document.getElementById('loginPassword').focus(); });
  document.getElementById('loginPassword').addEventListener('keydown', e => { if (e.key === 'Enter') loginUser(); });
  document.getElementById('goRegister').addEventListener('click', () => navigate('/register'));
}

/* ══════════════════════════════════════════════════
   REGISTER
══════════════════════════════════════════════════ */
export function renderRegister() {
  document.getElementById('app').innerHTML = `
    <div class="screen screen-enter auth-page">

      <!-- Full-screen blurred background image -->
      <img src="${CAMPUS_SRC}" class="auth-campus-img" alt="" aria-hidden="true" />
      <div class="auth-bg-overlay"></div>

      <!-- Logo + app name -->
      <div class="auth-hero-content">
        <img src="${LOGO_SRC}" class="auth-uni-logo" alt="Christ University" />
        <div class="auth-app-name">Fliqr</div>
        <div class="auth-app-tagline">Create your account</div>
      </div>

      <!-- Glass register card -->
      <div class="auth-card">
        <div class="auth-card-title">Create account</div>

        <div class="auth-field-group">
          <div class="auth-field">
            <div class="auth-field-icon">
              <svg viewBox="0 0 20 20" fill="none"><circle cx="10" cy="7" r="3.5" stroke="currentColor" stroke-width="1.6"/><path d="M3 18c0-3.3 3.1-6 7-6s7 2.7 7 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
            </div>
            <input id="regName" type="text" placeholder="Full name" autocomplete="name" class="auth-input" />
          </div>
          <div class="auth-field">
            <div class="auth-field-icon">
              <svg viewBox="0 0 20 20" fill="none"><rect x="2" y="4" width="16" height="12" rx="2" stroke="currentColor" stroke-width="1.6"/><path d="M3 6l6.5 5a1.5 1.5 0 001.8 0L18 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
            </div>
            <input id="regEmail" type="email" placeholder="your@gmail.com" autocomplete="email" class="auth-input" />
          </div>
          <div class="auth-field" style="border-bottom:none">
            <div class="auth-field-icon">
              <svg viewBox="0 0 20 20" fill="none"><rect x="4" y="9" width="12" height="8" rx="1.5" stroke="currentColor" stroke-width="1.6"/><path d="M7 9V6.5a3 3 0 016 0V9" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
            </div>
            <input id="regPassword" type="password" placeholder="Min. 6 characters" autocomplete="new-password" class="auth-input" />
          </div>
        </div>

        <button class="btn auth-btn" id="registerBtn">Continue →</button>

        <div class="auth-switch">
          Already have an account?
          <span id="goLogin" class="auth-switch-link">Sign in</span>
        </div>
      </div>
    </div>`;

  document.getElementById('registerBtn').addEventListener('click', registerUser);
  document.getElementById('regName').addEventListener('keydown', e => { if (e.key === 'Enter') document.getElementById('regEmail').focus(); });
  document.getElementById('regEmail').addEventListener('keydown', e => { if (e.key === 'Enter') document.getElementById('regPassword').focus(); });
  document.getElementById('regPassword').addEventListener('keydown', e => { if (e.key === 'Enter') registerUser(); });
  document.getElementById('goLogin').addEventListener('click', () => navigate('/login'));
}

/* ══════════════════════════════════════════════════
   HELPER — map DB user → frontend state
══════════════════════════════════════════════════ */
function dbUserToState(dbUser) {
  return {
    uid:         dbUser._id        || '',
    name:        dbUser.username   || '',
    email:       dbUser.email      || '',
    year:        dbUser.year       || '',
    department:  dbUser.department || '',
    bio:         dbUser.bio        || '',
    icebreaker:  dbUser.icebreaker || '',
    interests:   dbUser.interests  || [],
    lookingFor:  dbUser.lookingFor || [],
    openTo:      dbUser.openTo     || ['Everyone'],
    photoURL:    dbUser.photoURL   || '',
    coverURL:    dbUser.coverURL   || '',
    profileDone: dbUser.profileDone || false,
  };
}

/* ══════════════════════════════════════════════════
   ACTIONS
══════════════════════════════════════════════════ */
async function registerUser() {
  const name     = document.getElementById('regName').value.trim();
  const email    = document.getElementById('regEmail').value.trim();
  const password = document.getElementById('regPassword').value;

  if (!name || !email || !password) { toast('Please fill in all fields', 'error'); return; }
  if (password.length < 6) { toast('Password must be at least 6 characters', 'error'); return; }

  const btn = document.getElementById('registerBtn');
  btn.disabled = true; btn.innerHTML = '<span class="spinner"></span> Creating account…';

  try {
    const r1 = await fetch(`${API_URL}/auth/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: name, email, password }),
    });
    const d1 = await r1.json();
    if (!r1.ok) throw new Error(d1.message || 'Registration failed');

    const r2 = await fetch(`${API_URL}/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });
    const d2 = await r2.json();
    if (!r2.ok) throw new Error('Registered! Please sign in.');

    localStorage.setItem('token', d2.token);
    setState({ currentUser: dbUserToState(d2.user || {}) });

    toast('Account created! Now set up your profile 🎉', 'success');
    navigate('/setup');

  } catch (err) {
    console.error(err);
    toast(err.message || 'Registration failed', 'error');
    btn.disabled = false; btn.textContent = 'Continue →';
  }
}

async function loginUser() {
  const email    = document.getElementById('loginEmail').value.trim();
  const password = document.getElementById('loginPassword').value;

  if (!email || !password) { toast('Please enter your email and password', 'error'); return; }

  const btn = document.getElementById('loginBtn');
  btn.disabled = true; btn.innerHTML = '<span class="spinner"></span> Signing in…';

  try {
    const res  = await fetch(`${API_URL}/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.message || 'Login failed');

    localStorage.setItem('token', data.token);
    const user = dbUserToState(data.user || {});
    setState({ currentUser: user });

    toast('Welcome back! 👋', 'success');
    navigate(user.profileDone ? '/discover' : '/setup');

  } catch (err) {
    console.error(err);
    toast(err.message || 'Login failed', 'error');
    btn.disabled = false; btn.textContent = 'Sign in';
  }
}